def solve(g):
    from collections import deque
    h,w=len(g),len(g[0]); seen=set(); out=[row[:] for row in g]
    NB=[(dx,dy) for dx in(-1,0,1) for dy in(-1,0,1) if (dx,dy)!=(0,0)]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]; marker=None
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    v=g[x][y]
                    if v not in (0,1): marker=v
                    for dx,dy in NB:
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and g[a][b] and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                s=set(cells)
                for x,y in cells:
                    if all(0<=x+dx<h and 0<=y+dy<w and (x+dx,y+dy) in s for dx,dy in NB):
                        out[x][y]=marker
    return out
